#!/usr/bin/env bash
# Created by Lokinya (lokinyauv-create). Generated by AI (Claude, Anthropic). Apache-2.0.
# Removes VRChat Auto-Rejoin. Your kick history in ~/.local/state/vrchat-auto-rejoin stays.
set -uo pipefail
UNIT="$HOME/.config/systemd/user/vrchat-auto-rejoin.service"
LAUNCHER_CFG="$HOME/.config/vr-autolauncher/config.json"
if [ -f "$UNIT" ]; then
  systemctl --user disable --now vrchat-auto-rejoin.service 2>/dev/null
  rm -f "$UNIT"; systemctl --user daemon-reload 2>/dev/null
fi
if [ -f "$LAUNCHER_CFG" ]; then
  python3 -I - "$LAUNCHER_CFG" <<'PY'
import json, os, sys
path = sys.argv[1]
cfg = json.load(open(path, encoding="utf-8"))
cfg["apps"] = [a for a in cfg.get("apps", []) if "vrchat-auto-rejoin" not in a.get("command", "")]
tmp = path + ".tmp"
with open(tmp, "w", encoding="utf-8") as f:
    json.dump(cfg, f, ensure_ascii=False, indent=2)
os.replace(tmp, path)
PY
fi
pkill -x vrchat-rejoin 2>/dev/null
rm -rf "$HOME/.local/share/vrchat-auto-rejoin"
rm -f "$HOME/.local/bin/vrchat-auto-rejoin" "$HOME/.local/bin/vrchat-kicks" \
      "$HOME/.local/share/applications/vrchat-kicks.desktop"
echo "Removed / Видалено. History kept in ~/.local/state/vrchat-auto-rejoin"
